definition.script:
pipeline {
    agent any

    stages {
        stage('Compile & Test') {
            steps {
                echo 'Building and testing with Maven...'
                sh 'cd /mnt/c/Users/Reena/.gemini/antigravity/scratch/samplejava && mvn clean test'
            }
        }

        stage('Docker Build') {
            steps {
                echo 'Building Docker container...'
                sh 'cd /mnt/c/Users/Reena/.gemini/antigravity/scratch/samplejava && docker build -t samplejava:latest .'
            }
        }

        stage('Docker Run') {
            steps {
                echo 'Running Docker container and displaying output...'
                sh 'docker run --rm samplejava:latest'
            }
        }
    }
}
